(function(root){'use strict';const C=root.ArcadeCore,A=root.ArcadeArt;let run=null,raf=0,last=0,bounds=null,hover=null,message='',hints=0,fx=null;
const titles={block:['Block Puzzle','Embroidered shapes. A place for every little patch.'],bridge:['Bridge Adventure','A thoughtful path across the willow river.'],sort:['Color Garden','Bottled colors, blooming possibilities.']};
function records(){return state.arcadeProgress||{records:{},claims:[]}}
function unlocked(game,index){return index===0||!!records().records[game+':'+root.ArcadeGames[game].levels[index-1].id]}
function show(){cancelAnimationFrame(raf);run=null;content.innerHTML=greeting('Stay a little. Play a little.','Three small worlds, made for curious minds.','THE COZY ARCADE')+`<div class="arcade-catalog">${Object.keys(root.ArcadeGames).map(id=>`<button class="card arcade-cover" data-arcade="${id}"><canvas width="480" height="320" data-cover="${id}" aria-hidden="true"></canvas><div><small>${root.ArcadeGames[id].tag}</small><h2>${titles[id][0]}</h2><p>${titles[id][1]}</p><b>Enter little world →</b></div></button>`).join('')}</div><section id="arcade-stage" hidden></section>`;document.querySelectorAll('[data-cover]').forEach(canvas=>{const id=canvas.dataset.cover,G=root.ArcadeGames[id],m=G.create(G.levels[0]);A[id](A.baseCanvas(canvas),m,{equipped:state.equipped},0)});document.querySelectorAll('[data-arcade]').forEach(b=>b.onclick=()=>open(b.dataset.arcade))}
function open(game,index=0){cancelAnimationFrame(raf);const G=root.ArcadeGames[game];if(!G||!unlocked(game,index))return;run={game,index,model:G.create(G.levels[index]),phase:'title',cursor:{x:0,y:0},reward:0,clock:0};last=0;hover=null;hints=0;message='';fx=null;mount();loop(0)}
function shell(){const G=root.ArcadeGames[run.game],l=run.model.level;return `<div class="arcade-header"><button id="arcade-exit" class="secondary">← Arcade</button><div><small>${G.tag}</small><h2>${G.title}</h2></div><button id="arcade-pause" class="secondary">Pause</button></div><div class="arcade-stats"><span>Chapter ${run.index+1} / ${G.levels.length}</span><span id="arcade-moves"></span><span id="arcade-best"></span></div><div class="arcade-viewport"><canvas id="arcade-canvas" width="960" height="640" tabindex="0" role="application" aria-label="${G.title}: ${l.name}. ${G.instructions}"></canvas><div id="arcade-overlay"></div></div><div id="arcade-controls" class="arcade-controls"></div><p id="arcade-message" class="arcade-message" role="status" aria-live="polite"></p><div class="arcade-levels">${G.levels.map((l,i)=>`<button data-level="${i}" ${unlocked(run.game,i)?'':'disabled'} class="${i===run.index?'selected':''}">${i+1} · ${escapeHTML(l.name)} ${records().records[run.game+':'+l.id]?'★':''}</button>`).join('')}</div>`}
function mount(){const stage=$('#arcade-stage');if(!stage)return;stage.hidden=false;stage.innerHTML=shell();$('#arcade-exit').onclick=show;$('#arcade-pause').onclick=()=>pause();document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>open(run.game,Number(b.dataset.level)));const canvas=$('#arcade-canvas');canvas.addEventListener('pointerdown',e=>{if(run.phase!=='playing'||fx)return;e.preventDefault();const b=canvas.getBoundingClientRect(),point={x:(e.clientX-b.left)*480/b.width,y:(e.clientY-b.top)*320/b.height};interact(point);canvas.focus({preventScroll:true})});canvas.addEventListener('pointermove',e=>{if(run.game!=='block'||!bounds)return;const b=canvas.getBoundingClientRect();hover={x:Math.floor(((e.clientX-b.left)*480/b.width-bounds.x)/bounds.size),y:Math.floor(((e.clientY-b.top)*320/b.height-bounds.y)/bounds.size)}});canvas.addEventListener('pointerleave',()=>hover=null);canvas.addEventListener('keydown',key);update()}
function update(){if(!run)return;const G=root.ArcadeGames[run.game],m=run.model;$('#arcade-moves').textContent=m.moves+' moves · '+m.level.name;$('#arcade-best').textContent='Best '+(records().records[run.game+':'+m.level.id]?.score||'—');$('#arcade-message').textContent=message;const overlay=$('#arcade-overlay');const phase=run.phase;overlay.hidden=phase==='playing';$('#arcade-pause').disabled=phase==='title'||phase==='complete';if(phase==='title')overlay.innerHTML=`<div><small>CHAPTER ${run.index+1}</small><h3>${escapeHTML(m.level.name)}</h3><p>${escapeHTML(m.level.subtitle)}</p><button class="primary" id="arcade-start">Let’s play →</button><button class="secondary" id="arcade-help">How to play</button></div>`;if(phase==='instructions')overlay.innerHTML=`<div><h3>A little field guide</h3><p>${G.instructions}</p><p>Keyboard: arrow keys move the cursor; Enter selects or places. R rotates a patch, M mirrors where available, U undoes. Escape pauses.</p><button class="primary" id="arcade-start">I’m ready →</button></div>`;if(phase==='paused')overlay.innerHTML=`<div><small>TAKE YOUR TIME</small><h3>A little pause.</h3><p>Your puzzle will be right here.</p><button class="primary" id="arcade-resume">Keep playing</button><button class="secondary" id="arcade-restart">Restart chapter</button><button class="secondary" id="arcade-help">Instructions</button></div>`;if(phase==='complete')overlay.innerHTML=`<div><small>CHAPTER COMPLETE</small><h3>A lovely little victory.</h3><div class="arcade-stars">${'★'.repeat(run.stars)}${'☆'.repeat(3-run.stars)}</div><p>${run.score} points · ${m.moves} moves</p><p>${run.reward?'+'+run.reward+' coins earned':'Today’s coins already collected. Your best score can still improve.'}</p><button class="primary" id="arcade-next">${run.index<G.levels.length-1?'Next chapter →':'Back to arcade'}</button><button class="secondary" id="arcade-restart">Play again</button></div>`;
if($('#arcade-start'))$('#arcade-start').onclick=()=>{run.phase='playing';update();$('#arcade-canvas').focus({preventScroll:true})};if($('#arcade-help'))$('#arcade-help').onclick=()=>{run.phase='instructions';update()};if($('#arcade-resume'))$('#arcade-resume').onclick=()=>{run.phase='playing';update()};if($('#arcade-restart'))$('#arcade-restart').onclick=()=>open(run.game,run.index);if($('#arcade-next'))$('#arcade-next').onclick=()=>{if(run.index<G.levels.length-1)open(run.game,run.index+1);else show()};controls();}
function controls(){const m=run.model,G=root.ArcadeGames[run.game],disabled=run.phase!=='playing'?'disabled':'';let html='';if(run.game==='block'){html=`<div class="arcade-piece-tray">${m.level.pieces.map(p=>`<button data-patch="${p.id}" class="${m.selected===p.id?'selected':''}" ${disabled}><canvas data-patch-art="${p.id}" width="100" height="80" aria-hidden="true"></canvas><span>Patch ${p.id}${m.placements[p.id]?' · placed':''}</span></button>`).join('')}</div><button id="arcade-rotate" class="secondary" ${disabled}>Rotate ↻</button>${m.level.mirror?`<button id="arcade-mirror" class="secondary" ${disabled}>Mirror ↔</button>`:''}<button id="arcade-hint" class="secondary" ${disabled}>A little hint</button>`}html+=`<button id="arcade-undo" class="secondary" ${disabled}>Undo</button><button id="arcade-reset" class="secondary" ${disabled}>Restart</button>`;$('#arcade-controls').innerHTML=html;
if(run.game==='block'){document.querySelectorAll('[data-patch-art]').forEach(canvas=>{const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const p=m.level.pieces.find(p=>p.id===canvas.dataset.patchArt);for(const [x,y]of p.cells)A.patch(c,4+x*15,4+y*15,14,A.colors[p.color%A.colors.length],p.color)});document.querySelectorAll('[data-patch]').forEach(b=>b.onclick=()=>{m.selected=b.dataset.patch;m.turn=0;m.mirror=false;message='Patch '+m.selected+' selected.';update()});$('#arcade-rotate').onclick=()=>{m.turn=(m.turn+1)%4;hover=run.cursor;update()};if($('#arcade-mirror'))$('#arcade-mirror').onclick=()=>{m.mirror=!m.mirror;update()};$('#arcade-hint').onclick=()=>{hints++;message='Try a different rotation, or make room for the longest patch first. Hints reduce the final score.';const id=m.selected,rows=m.level.solution;hover=null;run.hint=rows.flatMap((row,y)=>[...row].flatMap((v,x)=>v===id?[[x,y]]:[]));update()}}
$('#arcade-undo').onclick=()=>{if(G.undo(m)){message='One move back. A fresh possibility.';fx=null;update()}};$('#arcade-reset').onclick=()=>{run.phase='paused';message='Restart from the pause menu, or keep your progress.';update()}}
function interact(point){if(run.game!=='block')return;if(!bounds)return;const x=Math.floor((point.x-bounds.x)/bounds.size),y=Math.floor((point.y-bounds.y)/bounds.size);if(x<0||x>=bounds.w||y<0||y>=bounds.h)return;const G=root.ArcadeGames.block,m=run.model,id=G.occupied(m)[x+','+y];if(G.place(m,x,y)){message='A perfect little fit.';run.hint=null;fx={kind:'place',start:run.clock,x:point.x,y:point.y}}else if(id){G.remove(m,id);message='Patch '+id+' lifted.'}else{message='That patch needs a different place or rotation.';fx={kind:'invalid',start:run.clock,x:point.x,y:point.y}}update();finish()}
function finish(){const G=root.ArcadeGames[run.game];if(run.phase!=='playing'||!G.solved(run.model))return;run.score=Math.max(100,G.score(run.model)-hints*100);run.stars=Math.max(1,C.stars(run.model.moves,run.model.level.par)-(hints?1:0));const result=C.award(records(),run.game,run.model.level.id,run.score,run.stars,new Date().toLocaleDateString('en-CA'));state.arcadeProgress=result.progress;state.coins+=result.reward;run.reward=result.reward;save();celebrationUntil=Date.now()+3500;run.phase='complete';update()}
function pause(){if(!run)return;if(run.phase==='playing'){run.phase='paused';update()}else if(run.phase==='paused'){run.phase='playing';update()}}
function key(e){if(!run)return;if(e.key==='Escape'){e.preventDefault();pause();return}if(run.phase!=='playing'||fx)return;const m=run.model;if(run.game==='block'){const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(d){e.preventDefault();run.cursor={x:Math.max(0,Math.min(m.level.w-1,run.cursor.x+d[0])),y:Math.max(0,Math.min(m.level.h-1,run.cursor.y+d[1]))}};hover=run.cursor;if(e.key.toLowerCase()==='r'){m.turn=(m.turn+1)%4;update()}if(e.key.toLowerCase()==='m'&&m.level.mirror){m.mirror=!m.mirror;update()}if(e.key==='Enter'||e.key===' '){e.preventDefault();interact({x:bounds.x+(run.cursor.x+.5)*bounds.size,y:bounds.y+(run.cursor.y+.5)*bounds.size})}}if(e.key.toLowerCase()==='u'){$('#arcade-undo').click()}}
function loop(t){if(!run||page!=='games'){cancelAnimationFrame(raf);return}if(t-last>=32){if(run.phase==='playing'||run.phase==='complete')run.clock+=Math.min(80,t-last);const canvas=$('#arcade-canvas');if(!canvas)return;const c=A.baseCanvas(canvas);bounds=A[run.game](c,run.model,{hover:run.phase==='playing'?hover:null,hint:run.hint,equipped:state.equipped,won:run.phase==='complete'},run.clock);if(fx){const age=run.clock-fx.start;if(age>400)fx=null;else{const {r}=A.tools(c);for(let i=0;i<7;i++){const a=i*Math.PI*2/7,dist=age/25;r(fx.x+Math.cos(a)*dist,fx.y+Math.sin(a)*dist,2,2,fx.kind==='invalid'?A.P.rose:A.P.gold)}}}last=t}raf=requestAnimationFrame(loop)}
if(root.document)document.addEventListener('visibilitychange',()=>{if(document.hidden&&run?.phase==='playing')pause()});root.DiaArcade={show,open};
})(typeof window!=='undefined'?window:globalThis);
